const BY_ID = new Map(BSA_SECTIONS.map((s) => [s.id, s]))

export function bsaSectionById(id: string) {
  return BY_ID.get(id)
}

export function bsaSectionsInChapter(chapter: string) {
  return BSA_SECTIONS.filter((s) => s.chapter === chapter)
}

export function bsaSectionTopicId(sectionId: string) {
  return `s-${sectionId.toLowerCase()}`
}

export function bsaSectionIdFromTopicId(topicId: string): string | null {
  const match = topicId.match(/^s-(\d+[a-z]*)$/i)
  return match?.[1] ?? null
}

